code:
struct A { A() { std::cout << "A"; } ~A() { std::cout << "a"; } };
  struct B { B() { std::cout << "B"; } ~B() { std::cout << "b"; } };
  struct C { A x; B y; C() { std::cout << "C"; } ~C() { std::cout << "c"; } };
  int main() { C c; }

struct M { M() { std::cout << "M"; } ~M() { std::cout << "m"; } };
  struct B { B() { std::cout << "B"; } ~B() { std::cout << "b"; } };
  struct D : B { M m; D() { std::cout << "D"; } ~D() { std::cout << "d"; } };
  int main() { D d; }

struct Base { void set(int) {} };
  struct Der : Base { void set(std::string) {} };
  Der d; d.set(5);

struct S { double f() const { return 1; } virtual double g() const { return 1; } virtual ~S() = default; };
  struct C : S { double f() const { return 2; } double g() const override { return 2; } };
  C c; const S& s = c; std::cout << s.f() << s.g();

struct P { virtual void f(int x = 1) { std::cout << "P" << x; } virtual ~P() = default; };
  struct Q : P { void f(int x = 2) override { std::cout << "Q" << x; } };
  P* p = new Q; p->f(); delete p;

struct A { virtual char n() const { return 'A'; } virtual ~A() = default; };
  struct B : A { char n() const override { return 'B'; } };
  std::vector<A> v{B{}}; std::cout << v[0].n();
